using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ReshapeCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Enemy/ReshapeCustomDescription", order = 0)]
public class ReshapeCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ReshapeAction reshapeAction = battleAction as ReshapeAction;
		return Smart.Format(GetRawLocalizedDescription(battleAction), reshapeAction.ActionToTransfigure.GetActionName(), reshapeAction.ActionValue);
	}
}
